/**
 * Bills Module - Recurring bill tracking and detection
 */
import { translate as t, translatePlural as n } from '@nextcloud/l10n';
import { once } from '../../utils/submitGuard.js';
import * as formatters from '../../utils/formatters.js';
import * as dom from '../../utils/dom.js';
import { billRowState, oneTimeDateUnconfirmed } from '../../utils/billDates.js';
import { showSuccess, showError, showWarning, showInfo, showUndoNotification } from '../../utils/notifications.js';
import { confirmDialog } from '../../utils/dialogs.js';
import { setDateValue, clearDateValue } from '../../utils/datepicker.js';
import { apiFetch } from '../../utils/api.js';
import { isoWeekday } from '../../utils/helpers.js';
import { showMatchingTransactionDialog } from '../../utils/matchingDialog.js';
import { offerableTags, offerableTagSets } from '../../utils/tags.js';
import { pickableAccounts, accountOptionLabel, selectAccountValue, accountCurrency, linkableCandidates, billAccountsWritable } from '../../utils/accounts.js';
import { showLoadError } from '../../utils/loading.js';
import { requestMarkUnpaid } from '../../utils/billUnpaid.js';

export default class BillsModule {
    constructor(app) {
        this.app = app;
        this._eventsSetup = false;
        this._detectedBills = [];
        this._undoTimer = null;
        this._undoData = null;
    }

    // Getters for app state
    get bills() { return this.app.bills; }
    set bills(value) { this.app.bills = value; }
    get accounts() { return this.app.accounts; }
    get categories() { return this.app.categories; }
    get categoryTree() { return this.app.categoryTree; }
    get settings() { return this.app.settings; }

    async loadBillsView() {
        // Before any fetch: a failed first load must not leave the view's
        // buttons (Add bill, filters) dead for the rest of the session.
        if (!this._eventsSetup) {
            this.setupBillsEventListeners();
            this._eventsSetup = true;
        }

        try {
            // Load summary first
            await this.loadBillsSummary();

            // Load all bills (excluding transfers). revertibleToo asks the
            // server to keep active bills plus inactive ones that still hold
            // a stored payment snapshot: a paid one-time bill leaves the
            // active list (#333), but must stay visible to be marked unpaid
            // (#365) — filtered server-side so the payload doesn't grow
            // forever with dead bills on old installs.
            this.bills = await apiFetch('/apps/budget/api/bills?isTransfer=false&revertibleToo=true');
            this.renderBills(this.bills);

            // Populate dropdowns in bill modal
            this.populateBillModalDropdowns();

            // Proactive suggestions (non-blocking)
            this.loadBillSuggestions();

            // Payments marked paid without a recorded transaction (non-blocking, #274)
            this.loadUnrecordedPayments();
        } catch (error) {
            console.error('Failed to load bills:', error);
            showError(t('budget', 'Failed to load bills'));
            const emptyBills = document.getElementById('empty-bills');
            if (emptyBills) emptyBills.style.display = 'none';
            showLoadError('bills-list', t('budget', 'Failed to load bills'), () => this.loadBillsView());
        }
    }

    /**
     * Surface bills recently marked paid with no recorded transaction — the
     * account balance does not reflect those payments (#274). Offers a
     * one-click "Record transaction" repair.
     */
    async loadUnrecordedPayments() {
        const card = document.getElementById('unrecorded-payments-card');
        const list = document.getElementById('unrecorded-payments-list');
        if (!card || !list) return;

        try {
            const data = await apiFetch('/apps/budget/api/bills/unrecorded-payments').catch(() => null);
            if (!data) {
                card.style.display = 'none';
                return;
            }
            const items = data.items || [];

            if (items.length === 0) {
                card.style.display = 'none';
                return;
            }

            const countBadge = document.getElementById('unrecorded-payments-count');
            if (countBadge) countBadge.textContent = String(data.count);

            list.innerHTML = items.map(item => {
                // Recording or reverting writes into the bill's accounts
                // (a transfer's destination too): only into ones you can
                // still write. Dismiss only notes it on your side.
                const writable = this.accounts === undefined || billAccountsWritable(item, this.accounts);
                return `
                <div class="unrecorded-payment-row">
                    <div class="bill-suggestion-info">
                        <strong>${dom.escapeHtml(item.name)}</strong>
                        <span class="bill-suggestion-meta">${t('budget', 'Marked paid on {date}', { date: formatters.formatDate(item.lastPaidDate, this.settings) })} &middot; ${formatters.formatCurrency(item.amount, item.currency, this.settings)}</span>
                        ${item.accountId && !writable ? `<span class="bill-account-hint">${t('budget', 'This bill uses an account you can no longer change. Edit the bill and choose another account.')}</span>` : ''}
                    </div>
                    <div class="bill-suggestion-actions">
                        ${item.accountId
                            ? (writable ? `<button class="primary unrecorded-payment-record" data-bill-id="${item.billId}">${t('budget', 'Record transaction')}</button>` : '')
                            : `<button class="unrecorded-payment-assign" data-bill-id="${item.billId}" title="${t('budget', 'One-time bills leave the list after payment — open it here to assign an account')}">${t('budget', 'Assign an account')}</button>`}
                        ${item.canMarkUnpaid && writable
                            ? `<button class="unrecorded-payment-unpaid" data-bill-id="${item.billId}" title="${t('budget', 'Revert the last payment')}">${t('budget', 'Mark Unpaid')}</button>`
                            : ''}
                        <button class="secondary unrecorded-payment-dismiss" data-bill-id="${item.billId}" title="${t('budget', 'Keep the bill as paid and stop listing this payment')}">${t('budget', 'Dismiss')}</button>
                    </div>
                </div>
            `;
            }).join('');

            list.querySelectorAll('.unrecorded-payment-record').forEach(btn => {
                btn.addEventListener('click', (e) => this.recordMissedPayment(parseInt(e.currentTarget.dataset.billId)));
            });

            // The bill may have been auto-deactivated (one-time bills leave the
            // active list after payment), so it can't be reached from the list to
            // assign an account — open the editor straight from the card (#333).
            list.querySelectorAll('.unrecorded-payment-assign').forEach(btn => {
                btn.addEventListener('click', (e) => this.editBill(parseInt(e.currentTarget.dataset.billId)));
            });

            // The two ways out other than recording the payment (#394): the
            // payment never happened (revert it, same action as the list) or it
            // did but is not meant to be in the ledger (dismiss this one).
            list.querySelectorAll('.unrecorded-payment-unpaid').forEach(btn => {
                btn.addEventListener('click', (e) => this.markBillUnpaid(parseInt(e.currentTarget.dataset.billId)));
            });
            list.querySelectorAll('.unrecorded-payment-dismiss').forEach(btn => {
                btn.addEventListener('click', (e) => this.dismissUnrecordedPayment(parseInt(e.currentTarget.dataset.billId)));
            });

            card.style.display = 'block';
        } catch (error) {
            card.style.display = 'none';
        }
    }

    /**
     * The missing transaction is deliberate (paid some other way, or the
     * ledger row was removed on purpose), so stop listing it. Covers this
     * one payment only: the bill's next unrecorded payment is flagged
     * again (#394).
     */
    async dismissUnrecordedPayment(billId) {
        try {
            await apiFetch(`/apps/budget/api/bills/${billId}/dismiss-unrecorded`, { method: 'POST' });
            await this.loadUnrecordedPayments();
        } catch (error) {
            showError(error.message || t('budget', 'Failed to dismiss the payment'));
        }
    }

    async recordMissedPayment(billId) {
        try {
            await apiFetch(`/apps/budget/api/bills/${billId}/record-payment`, { method: 'POST' });
            showSuccess(t('budget', 'Transaction recorded'));
            await this.loadBillsView();
            await this.app.loadAccounts();
        } catch (error) {
            showError(error.message || t('budget', 'Failed to record the payment'));
        }
    }

    /**
     * Proactive recurring-bill suggestions: payments that look recurring but
     * aren't tracked as bills yet. Dismissals are remembered server-side.
     */
    async loadBillSuggestions() {
        const card = document.getElementById('bill-suggestions-card');
        const list = document.getElementById('bill-suggestions-list');
        if (!card || !list) return;

        try {
            const data = await apiFetch('/apps/budget/api/bills/suggestions').catch(() => null);
            if (!data) {
                card.style.display = 'none';
                return;
            }
            this._billSuggestions = data.suggestions || [];

            if (this._billSuggestions.length === 0) {
                card.style.display = 'none';
                return;
            }

            const countBadge = document.getElementById('bill-suggestions-count');
            if (countBadge) countBadge.textContent = String(data.total);

            list.innerHTML = this._billSuggestions.map((item, index) => {
                const confidenceClass = item.confidence >= 0.8 ? 'high' : item.confidence >= 0.5 ? 'medium' : 'low';
                return `
                    <div class="bill-suggestion-row" data-index="${index}">
                        <div class="bill-suggestion-info">
                            <strong>${dom.escapeHtml(item.suggestedName || item.description)}</strong>
                            <span class="bill-suggestion-meta">${formatters.formatCurrency(item.amount, accountCurrency(this.accounts, item.accountId), this.settings)} &middot; ${item.frequency} &middot; <span class="detected-confidence ${confidenceClass}">${/* xgettext:no-javascript-format */ t('budget', '{percent}% confidence', { percent: Math.round(item.confidence * 100) })}</span></span>
                        </div>
                        <div class="bill-suggestion-actions">
                            <button class="primary bill-suggestion-create" data-index="${index}">${t('budget', 'Create bill')}</button>
                            <button class="secondary bill-suggestion-dismiss" data-index="${index}">${t('budget', 'Dismiss')}</button>
                        </div>
                    </div>
                `;
            }).join('');

            list.querySelectorAll('.bill-suggestion-create').forEach(btn => {
                btn.addEventListener('click', (e) => this.createBillFromSuggestion(parseInt(e.currentTarget.dataset.index)));
            });
            list.querySelectorAll('.bill-suggestion-dismiss').forEach(btn => {
                btn.addEventListener('click', (e) => this.dismissBillSuggestion(parseInt(e.currentTarget.dataset.index)));
            });
            const dismissAll = document.getElementById('bill-suggestions-dismiss-all');
            if (dismissAll && !dismissAll._bound) {
                dismissAll._bound = true;
                dismissAll.addEventListener('click', () => this.dismissAllBillSuggestions());
            }

            card.style.display = 'block';
        } catch (error) {
            card.style.display = 'none';
        }
    }

    /** One at a time: a double click created two (see utils/submitGuard.js) */
    createBillFromSuggestion(index) {
        return once(`bill-suggestion-${index}`, document.querySelector(`.bill-suggestion-create[data-index="${index}"]`), () => this._createBillFromSuggestion(index));
    }

    async _createBillFromSuggestion(index) {
        const item = this._billSuggestions?.[index];
        if (!item) return;
        try {
            await apiFetch('/apps/budget/api/bills/create-from-detected', {
                method: 'POST',
                body: { bills: [item] },
                errorMessage: t('budget', 'Failed to create bill'),
            });
            showSuccess(t('budget', 'Bill "{name}" created', { name: item.suggestedName || item.description }));
            await this.loadBillsView();
        } catch (error) {
            showError(t('budget', 'Failed to create bill: {message}', { message: error.message }));
        }
    }

    async dismissBillSuggestion(index) {
        const item = this._billSuggestions?.[index];
        if (!item) return;
        try {
            await apiFetch('/apps/budget/api/bills/suggestions/dismiss', {
                method: 'POST',
                body: { patternKey: item.patternKey },
            });
            await this.loadBillSuggestions();
        } catch (error) {
            showError(t('budget', 'Failed to dismiss suggestion'));
        }
    }

    async dismissAllBillSuggestions() {
        if (!this._billSuggestions?.length) return;
        if (!await confirmDialog(t('budget', 'Dismiss all suggestions? They will not be shown again.'))) return;
        try {
            for (const item of this._billSuggestions) {
                await apiFetch('/apps/budget/api/bills/suggestions/dismiss', {
                    method: 'POST',
                    body: { patternKey: item.patternKey },
                });
            }
            await this.loadBillSuggestions();
        } catch (error) {
            showError(t('budget', 'Failed to dismiss suggestions'));
        }
    }

    async loadBillsSummary() {
        try {
            const summary = await apiFetch('/apps/budget/api/bills/summary');

            // Update summary cards
            document.getElementById('bills-due-count').textContent = summary.dueThisMonth || 0;
            document.getElementById('bills-overdue-count').textContent = summary.overdue || 0;
            document.getElementById('bills-monthly-total').textContent = formatters.formatCurrency(summary.monthlyTotal || 0, summary.baseCurrency || null, this.settings);
            document.getElementById('bills-paid-count').textContent = summary.paidThisMonth || 0;
        } catch (error) {
            console.error('Failed to load bills summary:', error);
        }
    }

    renderBills(bills) {
        const billsList = document.getElementById('bills-list');
        const emptyBills = document.getElementById('empty-bills');

        if (!bills || bills.length === 0) {
            billsList.innerHTML = '';
            emptyBills.style.display = 'flex';
            return;
        }

        emptyBills.style.display = 'none';

        const today = formatters.getTodayDateString();
        billsList.innerHTML = bills.map(bill => {
            // Status, date and actions follow the bill's next occurrence, not
            // the calendar month (#399); an inactive bill only stays in this
            // list to be reverted (#365) and offers nothing to pay
            const row = billRowState(bill, today, this.settings, this.accounts);
            const statusClass = row.status;
            const statusText = row.statusText;

            const frequency = bill.frequency || 'monthly';
            const frequencyLabels = {
                'weekly': t('budget', 'Weekly'),
                'biweekly': t('budget', 'Bi-Weekly'),
                'semi-monthly': t('budget', 'Semi-Monthly'),
                'monthly': t('budget', 'Monthly'),
                'quarterly': t('budget', 'Quarterly'),
                'semi-annually': t('budget', 'Semi-Annually'),
                'yearly': t('budget', 'Yearly'),
                'one-time': t('budget', 'One-Time')
            };
            const frequencyLabel = frequencyLabels[frequency] || frequency.charAt(0).toUpperCase() + frequency.slice(1);

            const autoPayEnabled = bill.autoPayEnabled ?? bill.auto_pay_enabled ?? false;
            const autoPayFailed = bill.autoPayFailed ?? bill.auto_pay_failed ?? false;
            const remainingPayments = bill.remainingPayments ?? bill.remaining_payments ?? null;
            const endDate = bill.endDate ?? bill.end_date ?? null;
            const hasSplits = Array.isArray(bill.splitTemplate) && bill.splitTemplate.length >= 2;

            return `
                <div class="bill-card ${statusClass}" data-bill-id="${bill.id}" data-status="${statusClass}">
                    <div class="bill-header">
                        <div class="bill-info">
                            <h4 class="bill-name">${dom.escapeHtml(bill.name)}</h4>
                            <span class="bill-frequency">${frequencyLabel}</span>
                        </div>
                        <div class="bill-amount">${formatters.formatCurrency(bill.amount, bill.currency || null, this.settings)}</div>
                    </div>
                    <div class="bill-details">
                        <div class="bill-due-date">
                            <span class="icon-calendar" aria-hidden="true"></span>
                            ${dom.escapeHtml(row.dateText)}
                        </div>
                        <div class="bill-status ${statusClass}">
                            <span class="status-badge">${statusText}</span>
                            ${row.dateUnconfirmed ? `<span class="status-badge badge-extra badge-unconfirmed" title="${t('budget', 'This date was filled in for the bill, not entered. Edit the bill to check it.')}">${t('budget', 'Check date')}</span>` : ''}
                            ${hasSplits ? `<span class="status-badge badge-extra badge-split" title="${t('budget', 'Split across categories')}">${t('budget', 'Split')}</span>` : ''}
                            ${autoPayEnabled ? `<span class="status-badge badge-extra auto-pay" title="${t('budget', 'Auto-pay enabled')}"><span class="icon-checkmark"></span> ${t('budget', 'Auto-pay')}</span>` : ''}
                            ${autoPayFailed ? `<span class="status-badge badge-extra auto-pay-failed" title="${t('budget', 'Auto-pay failed - disabled')}"><span class="icon-error"></span> ${t('budget', 'Auto-pay Failed')}</span>` : ''}
                            ${remainingPayments !== null ? `<span class="status-badge badge-extra badge-neutral" title="${t('budget', 'Remaining payments')}">${t('budget', '{count} left', { count: remainingPayments })}</span>` : ''}
                            ${endDate ? `<span class="status-badge badge-extra badge-neutral" title="${t('budget', 'Ends {date}', { date: formatters.formatDate(endDate, this.settings) })}">${t('budget', 'Ends {date}', { date: formatters.formatDate(endDate, this.settings) })}</span>` : ''}
                        </div>
                    </div>
                    ${row.accountHint ? `<p class="bill-account-hint">${dom.escapeHtml(row.accountHint)}</p>` : ''}
                    <div class="bill-actions">
                        ${row.canPay ? `
                            <button class="bill-action-btn bill-paid-btn" data-bill-id="${bill.id}" title="${t('budget', 'Mark as paid')}">
                                <span class="icon-checkmark" aria-hidden="true"></span>
                                ${t('budget', 'Mark Paid')}
                            </button>
                        ` : ''}
                        ${row.canSkip ? `
                            <button class="bill-action-btn bill-skip-btn" data-bill-id="${bill.id}" title="${t('budget', 'Skip this payment')}">
                                <span aria-hidden="true">&#x23ED;</span>
                                ${t('budget', 'Skip')}
                            </button>
                        ` : ''}
                        ${row.canUnpay ? `
                            <button class="bill-action-btn bill-unpaid-btn" data-bill-id="${bill.id}" title="${t('budget', 'Revert the last payment')}">
                                <span class="icon-history" aria-hidden="true"></span>
                                ${t('budget', 'Mark Unpaid')}
                            </button>
                        ` : ''}
                        ${row.canWrite ? `<button class="bill-action-btn bill-edit-btn" data-bill-id="${bill.id}" title="${t('budget', 'Edit bill')}" aria-label="${t('budget', 'Edit bill')}">
                            <span class="icon-rename" aria-hidden="true"></span>
                        </button>` : ''}
                        ${bill._shared && !bill._canManage ? '' : `<button class="bill-action-btn bill-delete-btn" data-bill-id="${bill.id}" title="${t('budget', 'Delete bill')}" aria-label="${t('budget', 'Delete bill')}">
                            <span class="icon-delete" aria-hidden="true"></span>
                        </button>`}
                    </div>
                </div>
            `;
        }).join('');
    }

    filterBills(filter) {
        const billCards = document.querySelectorAll('.bill-card');
        billCards.forEach(card => {
            const status = card.dataset.status;
            let show = false;

            switch (filter) {
                case 'all':
                    show = true;
                    break;
                case 'due':
                    show = status === 'due-soon' || status === 'upcoming';
                    break;
                case 'overdue':
                    show = status === 'overdue';
                    break;
                case 'paid':
                    show = status === 'paid';
                    break;
                default:
                    show = true;
            }

            card.style.display = show ? 'flex' : 'none';
        });
    }

    setupBillsEventListeners() {
        // Add bill button
        const addBillBtn = document.getElementById('add-bill-btn');
        if (addBillBtn) {
            addBillBtn.addEventListener('click', () => this.showBillModal());
        }

        // Empty state add button
        const emptyBillsAddBtn = document.getElementById('empty-bills-add-btn');
        if (emptyBillsAddBtn) {
            emptyBillsAddBtn.addEventListener('click', () => this.showBillModal());
        }

        // Detect bills button
        const detectBillsBtn = document.getElementById('detect-bills-btn');
        if (detectBillsBtn) {
            detectBillsBtn.addEventListener('click', () => this.detectBills());
        }

        // Calendar feed subscription button
        const calendarFeedBtn = document.getElementById('bills-calendar-feed-btn');
        if (calendarFeedBtn) {
            calendarFeedBtn.addEventListener('click', () => this.showCalendarFeedModal());
        }

        // Bill form submission
        const billForm = document.getElementById('bill-form');
        if (billForm) {
            billForm.addEventListener('submit', (e) => {
                e.preventDefault();
                this.saveBill();
            });
        }

        // Bill modal cancel button
        const billModal = document.getElementById('bill-modal');
        if (billModal) {
            const cancelBtn = billModal.querySelector('.cancel-btn');
            if (cancelBtn) {
                cancelBtn.addEventListener('click', () => this.hideBillModal());
            }
        }

        // Bill frequency change (show/hide due month for yearly)
        const billFrequency = document.getElementById('bill-frequency');
        if (billFrequency) {
            billFrequency.addEventListener('change', () => this.updateBillFormFields());
        }

        // A weekly bill's start date sets its weekday. Picking a date also
        // confirms one that was filled in for the bill.
        const billStartDate = document.getElementById('bill-start-date');
        if (billStartDate) {
            billStartDate.addEventListener('change', () => {
                this.showDateUnconfirmed(false);
                this.updateBillFormFields();
            });
        }

        // Create transaction checkbox (show/hide date field)
        const createTransactionCheckbox = document.getElementById('bill-create-transaction');
        if (createTransactionCheckbox) {
            createTransactionCheckbox.addEventListener('change', (e) => {
                const dateGroup = document.getElementById('transaction-date-group');
                if (dateGroup) {
                    dateGroup.style.display = e.target.checked ? 'block' : 'none';
                }
            });
        }

        // Category change listener - load tag sets for selected category
        const billCategory = document.getElementById('bill-category');
        if (billCategory) {
            billCategory.addEventListener('change', () => {
                this.loadBillTagSets(billCategory.value || null, null);
            });
        }

        // Account dropdown change (enable/disable auto-pay checkbox + show currency)
        const billAccount = document.getElementById('bill-account');
        const autoPayCheckbox = document.getElementById('bill-auto-pay');
        if (billAccount && autoPayCheckbox) {
            billAccount.addEventListener('change', () => {
                this.syncAutoPayAvailability();
                this.updateBillAmountCurrency();
            });

            // Set initial state
            this.syncAutoPayAvailability();
        }

        // Bills filter tabs
        document.querySelectorAll('.bills-tabs .tab-button').forEach(tab => {
            tab.addEventListener('click', (e) => {
                document.querySelectorAll('.bills-tabs .tab-button').forEach(el => el.classList.remove('active'));
                e.target.classList.add('active');
                this.filterBills(e.target.dataset.filter);
            });
        });

        // Close detected panel
        const closeDetectedPanel = document.getElementById('close-detected-panel');
        if (closeDetectedPanel) {
            closeDetectedPanel.addEventListener('click', () => {
                document.getElementById('detected-bills-panel').style.display = 'none';
            });
        }

        // Cancel detected
        const cancelDetectedBtn = document.getElementById('cancel-detected-btn');
        if (cancelDetectedBtn) {
            cancelDetectedBtn.addEventListener('click', () => {
                document.getElementById('detected-bills-panel').style.display = 'none';
            });
        }

        // Add selected bills from detection
        const addSelectedBillsBtn = document.getElementById('add-selected-bills-btn');
        if (addSelectedBillsBtn) {
            addSelectedBillsBtn.addEventListener('click', () => this.addSelectedDetectedBills());
        }

        // Split template toggle
        const splitEnabled = document.getElementById('bill-split-enabled');
        if (splitEnabled) {
            splitEnabled.addEventListener('change', (e) => {
                const container = document.getElementById('bill-split-container');
                const categoryGroup = document.getElementById('bill-category').closest('.form-group');
                if (e.target.checked) {
                    container.style.display = 'block';
                    categoryGroup.style.display = 'none';
                    // Add initial rows if empty
                    const rows = document.getElementById('bill-split-rows');
                    if (!rows.children.length) {
                        this.addBillSplitRow();
                        this.addBillSplitRow();
                    }
                    this.updateBillSplitRemaining();
                } else {
                    container.style.display = 'none';
                    categoryGroup.style.display = '';
                }
            });
        }

        // Add split row button
        const addSplitBtn = document.getElementById('bill-add-split-btn');
        if (addSplitBtn) {
            addSplitBtn.addEventListener('click', () => {
                this.addBillSplitRow();
                this.updateBillSplitRemaining();
            });
        }

        // Bill amount change updates split remaining
        const billAmount = document.getElementById('bill-amount');
        if (billAmount) {
            billAmount.addEventListener('input', () => {
                if (document.getElementById('bill-split-enabled')?.checked) {
                    this.updateBillSplitRemaining();
                }
            });
        }

        // Delegated event handlers for bill actions
        document.addEventListener('click', (e) => {
            if (e.target.classList.contains('bill-edit-btn') || e.target.closest('.bill-edit-btn')) {
                const button = e.target.classList.contains('bill-edit-btn') ? e.target : e.target.closest('.bill-edit-btn');
                const billId = parseInt(button.dataset.billId);
                this.editBill(billId);
            } else if (e.target.classList.contains('bill-delete-btn') || e.target.closest('.bill-delete-btn')) {
                const button = e.target.classList.contains('bill-delete-btn') ? e.target : e.target.closest('.bill-delete-btn');
                const billId = parseInt(button.dataset.billId);
                this.deleteBill(billId);
            } else if (e.target.classList.contains('bill-paid-btn') || e.target.closest('.bill-paid-btn')) {
                const button = e.target.classList.contains('bill-paid-btn') ? e.target : e.target.closest('.bill-paid-btn');
                const billId = parseInt(button.dataset.billId);
                this.markBillPaid(billId);
            } else if (e.target.classList.contains('bill-skip-btn') || e.target.closest('.bill-skip-btn')) {
                const button = e.target.classList.contains('bill-skip-btn') ? e.target : e.target.closest('.bill-skip-btn');
                const billId = parseInt(button.dataset.billId);
                this.skipBillPayment(billId);
            } else if (e.target.classList.contains('bill-unpaid-btn') || e.target.closest('.bill-unpaid-btn')) {
                const button = e.target.classList.contains('bill-unpaid-btn') ? e.target : e.target.closest('.bill-unpaid-btn');
                const billId = parseInt(button.dataset.billId);
                this.markBillUnpaid(billId);
            }
        });
    }

    /**
     * The note under a one-time bill's date when the date was filled in for
     * it rather than entered (see oneTimeDateUnconfirmed()).
     *
     * @param {boolean} show
     */
    showDateUnconfirmed(show) {
        const note = document.getElementById('bill-start-date-unconfirmed');
        if (!note) return;
        note.textContent = show
            ? t('budget', 'This date was filled in for the bill when it was saved without one. Check it, then save.')
            : '';
        note.style.display = show ? '' : 'none';
    }

    showBillModal(bill = null) {
        const modal = document.getElementById('bill-modal');
        const title = document.getElementById('bill-modal-title');
        const form = document.getElementById('bill-form');

        form.reset();
        document.getElementById('bill-id').value = '';
        this.clearUnavailableOptions();

        if (bill) {
            title.textContent = t('budget', 'Edit Bill');
            document.getElementById('bill-id').value = bill.id;
            document.getElementById('bill-name').value = bill.name || '';
            document.getElementById('bill-description').value = bill.description || '';
            document.getElementById('bill-amount').value = bill.amount || '';
            document.getElementById('bill-frequency').value = bill.frequency || 'monthly';
            document.getElementById('bill-due-day').value = bill.dueDay || bill.due_day || '';
            document.getElementById('bill-due-month').value = bill.dueMonth || bill.due_month || '';
            // Both dropdowns only list what this user can see, so a bill shared
            // without its category or pay-from account used to fall back to ""
            // and saveBill sent null — stripping them off the owner's bill
            // (#370). Keep the real id selected instead.
            this.selectPossiblyUnavailable(
                document.getElementById('bill-category'),
                bill.categoryId ?? bill.category_id ?? null
            );
            // A closed account is offered as "(closed)", not as unavailable (#372)
            const billAccountSelect = document.getElementById('bill-account');
            const billAccountId = bill.accountId ?? bill.account_id ?? null;
            if (!selectAccountValue(billAccountSelect, this.accounts, billAccountId)) {
                this.selectPossiblyUnavailable(billAccountSelect, billAccountId);
            }
            document.getElementById('bill-auto-pattern').value = bill.autoDetectPattern || bill.auto_detect_pattern || '';
            document.getElementById('bill-notes').value = bill.notes || '';
            const reminderDays = bill.reminderDays ?? bill.reminder_days;
            document.getElementById('bill-reminder-days').value = reminderDays !== null && reminderDays !== undefined ? reminderDays.toString() : '';

            // Parse and set custom recurrence pattern if present
            const customPattern = bill.customRecurrencePattern || bill.custom_recurrence_pattern;
            if (customPattern) {
                this.setCustomMonthsFromPattern(customPattern);
            } else {
                // Clear all month checkboxes
                document.querySelectorAll('#bill-custom-months input[type="checkbox"]').forEach(cb => cb.checked = false);
            }

            // Set start / end date / remaining payments. A one-time bill's
            // date lives in its start date; one stored only as its next due
            // date (from before the date field) opened with the date empty
            const storedStart = bill.startDate || bill.start_date || '';
            setDateValue('bill-start-date', storedStart
                || ((bill.frequency || 'monthly') === 'one-time' ? (bill.nextDueDate || bill.next_due_date || '') : ''));
            this.showDateUnconfirmed(oneTimeDateUnconfirmed(bill));
            setDateValue('bill-end-date', bill.endDate || bill.end_date || '');
            const remainingPayments = bill.remainingPayments ?? bill.remaining_payments;
            document.getElementById('bill-remaining-payments').value = remainingPayments !== null && remainingPayments !== undefined ? remainingPayments.toString() : '';

            // Populate the persistent pre-book flag (older bills without the
            // column count as enabled — that was the effective behaviour)
            document.getElementById('bill-create-transaction').checked =
                bill.createTransaction ?? bill.create_transaction ?? true;
            clearDateValue('bill-transaction-date');
            document.getElementById('transaction-date-group').style.display = 'none';

            // Set auto-pay fields
            const autoPayEnabled = bill.autoPayEnabled ?? bill.auto_pay_enabled ?? false;
            const autoPayFailed = bill.autoPayFailed ?? bill.auto_pay_failed ?? false;
            document.getElementById('bill-auto-pay').checked = autoPayEnabled;
            document.getElementById('auto-pay-failed-warning').style.display = autoPayFailed ? 'block' : 'none';
            const billExcludeEl = document.getElementById('bill-excluded-from-forecast');
            if (billExcludeEl) billExcludeEl.checked = bill.excludedFromForecast ?? bill.excluded_from_forecast ?? false;

            // Load the tag picker: global tags always, the category's tag sets
            // when it has one. Skipped for a bill with no category (every
            // split bill), saving then read no boxes and wiped its tags
            this.loadBillTagSets(bill.categoryId || bill.category_id || null, bill);

            // Populate split template
            const splitTemplate = bill.splitTemplate || bill.split_template || [];
            const splitCheckbox = document.getElementById('bill-split-enabled');
            const splitContainer = document.getElementById('bill-split-container');
            const splitRows = document.getElementById('bill-split-rows');
            const categoryGroup = document.getElementById('bill-category').closest('.form-group');
            splitRows.innerHTML = '';
            if (splitTemplate.length >= 2) {
                splitCheckbox.checked = true;
                splitContainer.style.display = 'block';
                categoryGroup.style.display = 'none';
                splitTemplate.forEach(split => this.addBillSplitRow(split));
                this.updateBillSplitRemaining();
            } else {
                splitCheckbox.checked = false;
                splitContainer.style.display = 'none';
                categoryGroup.style.display = '';
            }
        } else {
            title.textContent = t('budget', 'Add Bill');
            // Clear all month checkboxes for new bill
            document.querySelectorAll('#bill-custom-months input[type="checkbox"]').forEach(cb => cb.checked = false);

            // Clear start / end date / remaining payments
            clearDateValue('bill-start-date');
            this.showDateUnconfirmed(false);
            clearDateValue('bill-end-date');
            document.getElementById('bill-remaining-payments').value = '';

            // Pre-book is on by default for new bills (matches the app's
            // established mark-paid behaviour); untick to opt this bill out
            document.getElementById('bill-create-transaction').checked = true;
            clearDateValue('bill-transaction-date');
            document.getElementById('transaction-date-group').style.display = 'none';

            // Reset auto-pay fields for new bill
            document.getElementById('bill-auto-pay').checked = false;
            document.getElementById('auto-pay-failed-warning').style.display = 'none';
            const billExcludeNewEl = document.getElementById('bill-excluded-from-forecast');
            if (billExcludeNewEl) billExcludeNewEl.checked = false;

            // Clear tag sets
            const tagsContainer = document.getElementById('bill-tags-container');
            if (tagsContainer) tagsContainer.innerHTML = '';

            // Reset split template
            const splitCheckbox = document.getElementById('bill-split-enabled');
            if (splitCheckbox) splitCheckbox.checked = false;
            const splitContainer = document.getElementById('bill-split-container');
            if (splitContainer) splitContainer.style.display = 'none';
            const splitRows = document.getElementById('bill-split-rows');
            if (splitRows) splitRows.innerHTML = '';
            const categoryGroup = document.getElementById('bill-category').closest('.form-group');
            if (categoryGroup) categoryGroup.style.display = '';
        }

        this.updateBillFormFields();
        this.updateBillAmountCurrency();
        this.syncAutoPayAvailability();
        modal.style.display = 'flex';
        modal.setAttribute('aria-hidden', 'false');
    }

    /**
     * Drop the placeholder options a previous bill left behind, so a stale
     * "Unavailable" entry never lingers in the next bill's dropdowns.
     */
    clearUnavailableOptions() {
        ['bill-category', 'bill-account'].forEach(id => {
            const select = document.getElementById(id);
            if (!select) return;
            select.querySelectorAll('option[data-unavailable="1"], option[data-closed-account="1"]').forEach(opt => opt.remove());
        });
    }

    /**
     * Select `value` even when the dropdown holds no option for it — a shared
     * bill whose category or account was not shared alongside it. Assigning a
     * missing value silently yields "", which saveBill would then submit as
     * null, so add a disabled placeholder carrying the real id (#370).
     */
    selectPossiblyUnavailable(select, value) {
        if (!select) return;
        if (value === null || value === undefined || value === '') {
            select.value = '';
            return;
        }

        const wanted = String(value);
        select.value = wanted;
        if (select.value === wanted) return;

        const option = document.createElement('option');
        option.value = wanted;
        option.textContent = t('budget', 'Unavailable (not shared with you)');
        option.disabled = true;
        option.dataset.unavailable = '1';
        select.appendChild(option);
        select.value = wanted;
    }

    /**
     * Auto-pay needs a pay-from account. The account dropdown's change handler
     * was the only thing that worked that out, and setting a select's value in
     * code fires no change event — so opening an existing bill left the
     * checkbox greyed out even when the bill already had an account (#370).
     */
    syncAutoPayAvailability() {
        const accountSelect = document.getElementById('bill-account');
        const autoPayCheckbox = document.getElementById('bill-auto-pay');
        if (!accountSelect || !autoPayCheckbox) return;

        autoPayCheckbox.disabled = !accountSelect.value;
        if (autoPayCheckbox.disabled) autoPayCheckbox.checked = false;
    }

    hideBillModal() {
        const modal = document.getElementById('bill-modal');
        modal.style.display = 'none';
        modal.setAttribute('aria-hidden', 'true');
    }

    updateBillFormFields() {
        const frequency = document.getElementById('bill-frequency').value;
        const dueDayGroup = document.getElementById('due-day-group');
        const dueMonthGroup = document.getElementById('due-month-group');
        const customMonthsGroup = document.getElementById('custom-months-group');
        const startDateGroup = document.getElementById('start-date-group');
        const endDateGroup = document.getElementById('end-date-group');
        const remainingPaymentsGroup = document.getElementById('remaining-payments-group');

        // Show/hide custom months selector for custom frequency
        if (frequency === 'custom') {
            customMonthsGroup.style.display = 'block';
            dueDayGroup.style.display = 'block';
            dueMonthGroup.style.display = 'none';
        } else if (frequency === 'one-time') {
            // The Due Date below is the whole schedule (#375): day and month
            // are derived from it on save. Offering them as well left a bill
            // showing "Due Day 31, Due Month August" beside an empty Due Date,
            // and nothing to say which one counted (#333)
            customMonthsGroup.style.display = 'none';
            dueDayGroup.style.display = 'none';
            dueMonthGroup.style.display = 'none';
        } else if (frequency === 'yearly' || frequency === 'semi-annually' || frequency === 'quarterly') {
            // The month the cycle starts from. Hidden for quarterly and
            // half-yearly bills, they always fell on the January grid
            customMonthsGroup.style.display = 'none';
            dueDayGroup.style.display = 'block';
            dueMonthGroup.style.display = 'block';
        } else {
            customMonthsGroup.style.display = 'none';
            dueDayGroup.style.display = 'block';
            dueMonthGroup.style.display = 'none';
        }

        // A one-time bill is a single dated occurrence, so end date and
        // remaining payments mean nothing for it - but the start date field
        // becomes its actual due date, past allowed. Without a real date the
        // day+month pair always rolled forward, so an invoice from last month
        // could not be entered at all (#375).
        const isOneTime = frequency === 'one-time';
        if (startDateGroup) {
            startDateGroup.style.display = 'block';
            const startLabel = startDateGroup.querySelector('label');
            const startHelp = document.getElementById('bill-start-date-help');
            if (startLabel) {
                startLabel.textContent = isOneTime ? t('budget', 'Due Date') : t('budget', 'Start Date');
            }
            if (startHelp) {
                startHelp.textContent = isOneTime
                    ? t('budget', 'The date this bill is due. It can be in the past - an invoice you are entering late stays due on its own date.')
                    : t('budget', 'Bill only occurs on or after this date (optional)');
            }
            // With day and month hidden, the date is the only schedule a
            // one-time bill has, so it cannot be left blank
            const startInput = document.getElementById('bill-start-date');
            if (startInput) startInput.required = isOneTime;
        }
        if (endDateGroup) endDateGroup.style.display = isOneTime ? 'none' : 'block';
        if (remainingPaymentsGroup) remainingPaymentsGroup.style.display = isOneTime ? 'none' : 'block';

        // Update due day label based on frequency
        const dueDayLabel = dueDayGroup.querySelector('label');
        const dueDayHelp = document.getElementById('bill-due-day-help');

        const dueDayInput = document.getElementById('bill-due-day');
        dueDayInput.disabled = false;
        if (frequency === 'weekly' || frequency === 'biweekly') {
            dueDayLabel.textContent = t('budget', 'Due Day (1-7)');
            dueDayHelp.textContent = t('budget', 'Day of the week (1=Monday, 7=Sunday)');
            dueDayInput.max = 7;
            // With a start date the server counts the weeks from it and
            // ignores the weekday field, so the field follows the date
            // instead of contradicting it (as on the income and transfer forms)
            const anchor = document.getElementById('bill-start-date')?.value || '';
            if (anchor) {
                dueDayInput.value = String(isoWeekday(anchor));
                dueDayInput.disabled = true;
                dueDayHelp.textContent = t('budget', 'Follows the start date');
            }
        } else if (frequency === 'custom') {
            dueDayLabel.textContent = t('budget', 'Due Day');
            dueDayHelp.textContent = t('budget', 'Day of the selected months when bill is due');
            document.getElementById('bill-due-day').max = 31;
        } else {
            dueDayLabel.textContent = t('budget', 'Due Day');
            dueDayHelp.textContent = t('budget', 'Day of the month when bill is due');
            document.getElementById('bill-due-day').max = 31;
        }
    }

    populateBillModalDropdowns() {
        // Populate category dropdown
        const categorySelect = document.getElementById('bill-category');
        if (categorySelect && this.categories) {
            const currentValue = categorySelect.value;
            categorySelect.innerHTML = `<option value="">${t('budget', 'No category')}</option>`;
            dom.populateCategorySelect(categorySelect, this.categoryTree || this.categories, { typeFilter: 'expense' });
            if (currentValue) categorySelect.value = currentValue;
        }

        // Populate account dropdown (show currency in label)
        const accountSelect = document.getElementById('bill-account');
        if (accountSelect && this.accounts) {
            const currentValue = accountSelect.value;
            accountSelect.innerHTML = `<option value="">${t('budget', 'No specific account')}</option>`;
            // Closed accounts take no new bills; one already selected stays (#372)
            pickableAccounts(this.accounts, currentValue).forEach(acc => {
                const currencyLabel = acc.currency ? ` (${acc.currency})` : '';
                accountSelect.innerHTML += `<option value="${acc.id}">${dom.escapeHtml(accountOptionLabel(acc))}${currencyLabel}</option>`;
            });
            if (currentValue) accountSelect.value = currentValue;
        }
    }

    /**
     * Show/hide currency indicator next to the amount field based on selected account.
     */
    updateBillAmountCurrency() {
        const accountSelect = document.getElementById('bill-account');
        const amountInput = document.getElementById('bill-amount');
        if (!amountInput) return;

        // Remove existing currency indicator
        const existing = amountInput.parentElement.querySelector('.bill-currency-indicator');
        if (existing) existing.remove();

        if (accountSelect && accountSelect.value) {
            const account = this.accounts.find(a => a.id === parseInt(accountSelect.value));
            if (account && account.currency) {
                const indicator = document.createElement('span');
                indicator.className = 'bill-currency-indicator';
                indicator.textContent = account.currency;
                indicator.style.cssText = 'margin-left: 8px; color: var(--color-text-maxcontrast); font-size: 0.9em; font-weight: 500;';
                amountInput.parentElement.appendChild(indicator);
            }
        }
    }

    addBillSplitRow(split = null) {
        const container = document.getElementById('bill-split-rows');
        const row = document.createElement('div');
        row.className = 'bill-split-row';
        row.style.cssText = 'display: flex; gap: 8px; align-items: center; margin-bottom: 6px;';

        // Amount input
        const amountInput = document.createElement('input');
        amountInput.type = 'number';
        amountInput.step = '0.01';
        amountInput.min = '0';
        amountInput.placeholder = t('budget', 'Amount');
        amountInput.className = 'bill-split-amount';
        amountInput.style.cssText = 'width: 100px; flex-shrink: 0;';
        amountInput.value = split?.amount || '';
        amountInput.addEventListener('input', () => this.updateBillSplitRemaining());

        // Category select
        const categorySelect = document.createElement('select');
        categorySelect.className = 'bill-split-category';
        categorySelect.style.cssText = 'flex: 1;';
        categorySelect.innerHTML = `<option value="">${t('budget', 'No category')}</option>`;
        dom.populateCategorySelect(categorySelect, this.categoryTree || this.categories, { typeFilter: 'expense' });
        // A shared bill's part may be filed under a category not shared with
        // you: keep it, or the save would clear it (#370)
        if (split?.categoryId) this.selectPossiblyUnavailable(categorySelect, split.categoryId);

        // Description input
        const descInput = document.createElement('input');
        descInput.type = 'text';
        descInput.placeholder = t('budget', 'Description (optional)');
        descInput.className = 'bill-split-description';
        descInput.style.cssText = 'flex: 1;';
        descInput.value = split?.description || '';

        // Remove button
        const removeBtn = document.createElement('button');
        removeBtn.type = 'button';
        removeBtn.className = 'bill-split-remove';
        removeBtn.textContent = '\u00d7';
        removeBtn.title = t('budget', 'Remove split');
        removeBtn.setAttribute('aria-label', removeBtn.title);
        removeBtn.style.cssText = 'width: 28px; height: 28px; padding: 0; border: none; background: var(--color-error); color: white; border-radius: 50%; cursor: pointer; font-size: 16px; flex-shrink: 0;';
        removeBtn.addEventListener('click', () => {
            row.remove();
            this.updateBillSplitRemaining();
        });

        row.appendChild(amountInput);
        row.appendChild(categorySelect);
        row.appendChild(descInput);
        row.appendChild(removeBtn);
        container.appendChild(row);
    }

    updateBillSplitRemaining() {
        const totalAmount = parseFloat(document.getElementById('bill-amount')?.value) || 0;
        const rows = document.querySelectorAll('.bill-split-row');
        let allocated = 0;
        rows.forEach(row => {
            allocated += parseFloat(row.querySelector('.bill-split-amount')?.value) || 0;
        });
        const remaining = totalAmount - allocated;
        const el = document.getElementById('bill-split-remaining');
        // In the chosen account's currency, the one the form's amount is in
        const currency = accountCurrency(this.accounts, document.getElementById('bill-account')?.value);
        if (el) {
            const absRemaining = Math.abs(remaining);
            if (absRemaining < 0.01) {
                el.textContent = t('budget', 'Balanced');
                el.style.color = 'var(--color-success)';
            } else if (remaining > 0) {
                el.textContent = t('budget', '{amount} remaining', { amount: formatters.formatCurrency(remaining, currency, this.settings) });
                el.style.color = 'var(--color-warning)';
            } else {
                el.textContent = t('budget', '{amount} over', { amount: formatters.formatCurrency(absRemaining, currency, this.settings) });
                el.style.color = 'var(--color-error)';
            }
        }
    }

    getBillSplitTemplate() {
        if (!document.getElementById('bill-split-enabled')?.checked) {
            return null;
        }
        const rows = document.querySelectorAll('.bill-split-row');
        if (rows.length < 2) return null;

        const splits = [];
        rows.forEach(row => {
            const amount = parseFloat(row.querySelector('.bill-split-amount')?.value) || 0;
            if (amount > 0) {
                splits.push({
                    categoryId: row.querySelector('.bill-split-category')?.value ? parseInt(row.querySelector('.bill-split-category').value) : null,
                    amount: amount,
                    description: row.querySelector('.bill-split-description')?.value || null,
                });
            }
        });
        return splits.length >= 2 ? splits : null;
    }

    /** One at a time: a double click created two (see utils/submitGuard.js) */
    saveBill() {
        return once('bill-save', document.querySelector('#bill-form [type="submit"]'), () => this._saveBill());
    }

    async _saveBill() {
        const billId = document.getElementById('bill-id').value;
        const isNew = !billId;

        const reminderValue = document.getElementById('bill-reminder-days').value;
        const frequency = document.getElementById('bill-frequency').value;

        const billData = {
            name: document.getElementById('bill-name').value,
            description: document.getElementById('bill-description').value || null,
            amount: parseFloat(document.getElementById('bill-amount').value),
            frequency: frequency,
            dueDay: document.getElementById('bill-due-day').value ? parseInt(document.getElementById('bill-due-day').value) : null,
            // A month the form doesn't show is a stale value, not a schedule
            dueMonth: ['yearly', 'semi-annually', 'quarterly'].includes(frequency) && document.getElementById('bill-due-month').value
                ? parseInt(document.getElementById('bill-due-month').value) : null,
            categoryId: document.getElementById('bill-category').value ? parseInt(document.getElementById('bill-category').value) : null,
            accountId: document.getElementById('bill-account').value ? parseInt(document.getElementById('bill-account').value) : null,
            autoDetectPattern: document.getElementById('bill-auto-pattern').value || null,
            notes: document.getElementById('bill-notes').value || null,
            reminderDays: reminderValue !== '' ? parseInt(reminderValue) : null,
            createTransaction: document.getElementById('bill-create-transaction')?.checked || false,
            transactionDate: document.getElementById('bill-transaction-date')?.value || null,
            autoPayEnabled: document.getElementById('bill-auto-pay')?.checked || false,
            excludedFromForecast: document.getElementById('bill-excluded-from-forecast')?.checked || false,
            tagIds: this.getSelectedBillTagIds(),
            startDate: document.getElementById('bill-start-date').value || null,
            endDate: document.getElementById('bill-end-date').value || null,
            remainingPayments: document.getElementById('bill-remaining-payments').value ? parseInt(document.getElementById('bill-remaining-payments').value) : null,
            splitTemplate: this.getBillSplitTemplate()
        };

        // The date input sits in a datepicker that hides the native one, so
        // its required flag is never enforced by the browser; without a date
        // the server put a one-time bill on 1 January next year (#399)
        if (frequency === 'one-time' && !billData.startDate) {
            showError(t('budget', 'Choose the date this bill is due'));
            return;
        }

        // A one-time bill's day and month follow its date (#375). The inputs
        // are hidden for it and may still hold a previous frequency's values
        if (frequency === 'one-time' && billData.startDate) {
            const [, month, day] = billData.startDate.split('-').map(Number);
            if (month && day) {
                billData.dueDay = day;
                billData.dueMonth = month;
            }
        }

        // When splits are defined, clear categoryId (splits define their own)
        if (billData.splitTemplate) {
            billData.categoryId = null;
        }

        // Add custom recurrence pattern if frequency is custom
        if (frequency === 'custom') {
            const customPattern = this.getCustomMonthsPattern();
            if (!customPattern) {
                showWarning(t('budget', 'Please select at least one month for custom frequency'));
                return;
            }
            billData.customRecurrencePattern = customPattern;
        } else {
            billData.customRecurrencePattern = null;
        }

        try {
            const url = isNew
                ? '/apps/budget/api/bills'
                : `/apps/budget/api/bills/${billId}`;

            await apiFetch(url, {
                method: isNew ? 'POST' : 'PUT',
                body: billData,
            });

            this.hideBillModal();
            showSuccess(isNew ? t('budget', 'Bill created successfully') : t('budget', 'Bill updated successfully'));
            await this.loadBillsView();
        } catch (error) {
            console.error('Failed to save bill:', error);
            showError(error.message || t('budget', 'Failed to save bill'));
        }
    }

    async editBill(billId) {
        try {
            const bill = await apiFetch(`/apps/budget/api/bills/${billId}`);
            this.showBillModal(bill);
        } catch (error) {
            console.error('Failed to load bill:', error);
            showError(t('budget', 'Failed to load bill'));
        }
    }

    async deleteBill(billId) {
        if (!await confirmDialog(t('budget', 'Are you sure you want to delete this bill?'), { destructive: true })) {
            return;
        }

        try {
            await apiFetch(`/apps/budget/api/bills/${billId}`, { method: 'DELETE' });

            showSuccess(t('budget', 'Bill deleted successfully'));
            await this.loadBillsView();
        } catch (error) {
            console.error('Failed to delete bill:', error);
            showError(t('budget', 'Failed to delete bill'));
        }
    }

    /**
     * Show the calendar-subscription modal: fetches (or creates) the user's
     * feed token and offers copyable webcal/https URLs plus regeneration.
     */
    async showCalendarFeedModal() {
        let feed;
        try {
            feed = await apiFetch('/apps/budget/api/calendar-feed');
        } catch (error) {
            console.error('Failed to fetch calendar feed info:', error);
            showError(t('budget', 'Failed to get calendar feed'));
            return;
        }

        const existing = document.getElementById('calendar-feed-modal');
        if (existing) existing.remove();

        const modal = document.createElement('div');
        modal.id = 'calendar-feed-modal';
        modal.className = 'modal';
        modal.style.display = 'flex';
        modal.innerHTML = `
            <div class="modal-content">
                <h3>${t('budget', 'Bills calendar subscription')}</h3>
                <p>${t('budget', 'Subscribe to this URL from any calendar app (Nextcloud Calendar, Thunderbird, your phone) to see upcoming bill due dates. Bills appear as all-day events for the next 12 months and refresh automatically.')}</p>
                <div class="form-group">
                    <label for="calendar-feed-url">${t('budget', 'Subscription URL')}</label>
                    <input type="text" id="calendar-feed-url" readonly value="${dom.escapeHtml(feed.webcalUrl)}">
                </div>
                <p class="form-text">⚠️ ${t('budget', 'Anyone with this URL can read your bill names and amounts. Regenerate the link if it leaks.')}</p>
                <div class="modal-buttons">
                    <button type="button" class="primary" id="calendar-feed-copy">${t('budget', 'Copy link')}</button>
                    <button type="button" class="secondary" id="calendar-feed-regenerate">${t('budget', 'Regenerate link')}</button>
                    <button type="button" class="secondary" id="calendar-feed-close">${t('budget', 'Close')}</button>
                </div>
            </div>
        `;
        document.body.appendChild(modal);

        modal.querySelector('#calendar-feed-copy').addEventListener('click', async () => {
            try {
                await navigator.clipboard.writeText(modal.querySelector('#calendar-feed-url').value);
                showSuccess(t('budget', 'Link copied to clipboard'));
            } catch (e) {
                modal.querySelector('#calendar-feed-url').select();
                showInfo(t('budget', 'Press Ctrl+C to copy the selected link'));
            }
        });

        modal.querySelector('#calendar-feed-regenerate').addEventListener('click', async () => {
            if (!await confirmDialog(t('budget', 'Regenerate the link? Existing calendar subscriptions will stop updating.'))) return;
            try {
                const fresh = await apiFetch('/apps/budget/api/calendar-feed/regenerate', { method: 'POST' });
                modal.querySelector('#calendar-feed-url').value = fresh.webcalUrl;
                showSuccess(t('budget', 'New link generated'));
            } catch (error) {
                showError(t('budget', 'Failed to regenerate calendar feed token'));
            }
        });

        modal.querySelector('#calendar-feed-close').addEventListener('click', () => modal.remove());
        modal.addEventListener('click', (e) => { if (e.target === modal) modal.remove(); });
    }

    async markBillPaid(billId) {
        try {
            const bill = this.bills.find(b => b.id === billId);
            if (!bill) {
                throw new Error('Bill not found');
            }

            // Check for existing matching transactions before creating a new one
            if (bill.accountId || bill.account_id) {
                const found = await apiFetch(`/apps/budget/api/bills/${billId}/matching-transactions`)
                    .catch(() => null);
                // Only rows the payment can be linked to
                const candidates = found ? linkableCandidates(found, this.accounts) : null;

                if (candidates) {
                    if (candidates.length > 0) {
                        // Show dialog and let user choose
                        const choice = await this._showMatchingTransactionDialog(bill, candidates);
                        if (choice === null) {
                            return; // User cancelled
                        }
                        await this._executeMarkPaid(billId, bill, choice);
                        return;
                    }
                }
            }

            // No matches found — proceed with normal flow (create new transaction)
            await this._executeMarkPaid(billId, bill, { action: 'create' });

        } catch (error) {
            console.error('Failed to mark bill as paid:', error);
            showError(error.message || t('budget', 'Failed to mark bill as paid'));
        }
    }

    /**
     * Execute the mark paid API call with the user's choice.
     * @param {number} billId
     * @param {object} bill
     * @param {object} choice - {action: 'create'|'link'|'skip', transactionId?: number}
     */
    async _executeMarkPaid(billId, bill, choice) {
        const body = {};

        // recordPayment covers this payment only. Whether the ledger carries a
        // row for the next occurrence is the bill's own setting, on the server
        // side - it used to ride on this flag, so linking or skipping left the
        // bill with nothing upcoming at all (#376).
        if (choice.action === 'link') {
            body.existingTransactionId = choice.transactionId;
            body.recordPayment = false;
        } else if (choice.action === 'skip') {
            body.recordPayment = false;
        } else {
            body.recordPayment = true;
        }
        // The occurrence this row showed: a second click or a stale tab is
        // refused by the server instead of paying it twice
        body.dueDate = bill.nextDueDate || bill.next_due_date || null;

        const result = await apiFetch(`/apps/budget/api/bills/${billId}/paid`, {
            method: 'POST',
            body,
        });

        // Store undo data BEFORE reloading; the server keeps what to revert
        const undoData = { billId: billId, action: 'markPaid' };
        this._undoData = undoData;

        await this.loadBillsView();

        let message;
        if (choice.action === 'link' && result.paymentTransactionRecorded !== false) {
            message = t('budget', 'Bill marked as paid. Linked to existing transaction.');
        } else if (choice.action === 'skip') {
            // The user opted out of recording the payment — still warn, because
            // this is exactly how balances silently drift from the bank (#274)
            showWarning(t('budget', 'No transaction was recorded for this payment — your account balance will not reflect it.'));
            message = t('budget', 'Bill marked as paid. No transaction created.');
        } else if (result.paymentTransactionRecorded === false) {
            // The server marked the bill paid but recorded NO money movement
            // (e.g. the bill has no account, or transaction creation failed).
            // Without this warning the account balance silently drifts from
            // the real bank balance (#89, #274).
            if (choice.action === 'link') {
                // The transaction exists (balance is fine) — only the bill
                // linkage failed, so say that instead of the balance warning.
                showWarning(t('budget', 'The bill was marked as paid, but linking the selected transaction failed. You can link it manually from the transaction.'));
            } else {
                showWarning(t('budget', 'No transaction was recorded for this payment — your account balance will not reflect it. Assign an account to the bill, or add the transaction manually.'));
            }
            message = t('budget', 'Bill marked as paid — without a transaction.');
        } else {
            // Only say a future transaction was created when one was: the
            // bill pre-books, has an account and has a next occurrence
            const paid = result.bill || bill;
            const preBooks = (paid.createTransaction ?? paid.create_transaction ?? bill.createTransaction ?? true)
                && (paid.accountId || paid.account_id || bill.accountId || bill.account_id)
                && (paid.isActive ?? paid.is_active ?? true)
                && bill.frequency !== 'one-time';
            message = preBooks
                ? t('budget', 'Bill marked as paid. Future transaction created.')
                : t('budget', 'Bill marked as paid. Transaction created.');
        }
        // The toast undoes this payment, whatever was done since
        showUndoNotification(message, () => this.undoMarkBillPaid(undoData), () => this._dropUndo(undoData));
    }

    /**
     * An undo toast ran out: its action can't be undone any more. A later
     * action may have replaced the latest undo data; only drop our own.
     */
    _dropUndo(undoData) {
        undoData.spent = true;
        if (this._undoData === undoData) this._undoData = null;
    }

    /**
     * Show a dialog presenting matching transaction candidates.
     * Returns a Promise that resolves with the user's choice or null if cancelled.
     */
    _showMatchingTransactionDialog(bill, candidates) {
        return showMatchingTransactionDialog(bill, candidates, this.settings);
    }

    /**
     * @param {object} undoData - The payment to undo; each toast passes its
     *   own, so an older toast never reverts a later action
     */
    async undoMarkBillPaid(undoData = this._undoData) {
        if (!undoData || undoData.spent || undoData.action !== 'markPaid') {
            return;
        }
        undoData.spent = true;

        try {
            // The server reverts from the snapshot it stored on the bill
            const { billId } = undoData;

            await apiFetch(`/apps/budget/api/bills/${billId}/undo-paid`, {
                method: 'POST',
            });

            if (this._undoData === undoData) this._undoData = null;
            await this.loadBillsView();

            showSuccess(t('budget', 'Action undone'));
        } catch (error) {
            console.error('Failed to undo mark paid:', error);
            showError(t('budget', 'Failed to undo action: {message}', { message: error.message }));
        }
    }

    /**
     * Durable "mark as unpaid" (#365): reverts the last payment from the
     * snapshot the server persisted on markPaid. Unlike the undo toast, this
     * works after a reload — and for auto-paid or import-matched bills that
     * never showed a toast at all.
     */
    async markBillUnpaid(billId) {
        const bill = (this.bills || []).find(b => b.id === billId);
        // Created transactions are deleted; a payment recorded by linking an
        // imported transaction is only unlinked — the copy must not claim a
        // deletion that will not happen.
        let message = t('budget', 'Mark this bill as unpaid? Transactions created for the payment will be deleted, a linked imported transaction will be unlinked, and the bill schedule rolled back.');
        const autoPayEnabled = bill ? (bill.autoPayEnabled ?? bill.auto_pay_enabled ?? false) : false;
        if (autoPayEnabled) {
            // Reverting does not touch auto-pay — warn instead of silently
            // changing a setting the user chose.
            message += '\n\n' + t('budget', 'Auto-pay is on for this bill — it may pay it again on the next run. Disable auto-pay first if the payment should not recur.');
        }
        if (!await confirmDialog(message, { destructive: true })) {
            return;
        }

        try {
            // Asks again when the payment was reconciled against a statement
            if (!await requestMarkUnpaid(billId, t('budget', 'Failed to mark bill as unpaid'))) {
                return;
            }

            await this.loadBillsView();
            showSuccess(t('budget', 'Payment reverted — the bill is marked as unpaid.'));
        } catch (error) {
            console.error('Failed to mark bill as unpaid:', error);
            showError(error.message || t('budget', 'Failed to mark bill as unpaid'));
        }
    }

    async skipBillPayment(billId) {
        try {
            const bill = this.bills.find(b => b.id === billId);
            if (!bill) {
                throw new Error('Bill not found');
            }

            if (!await confirmDialog(t('budget', 'Skip this payment and advance to the next due date?'))) {
                return;
            }

            const result = await apiFetch(`/apps/budget/api/bills/${billId}/skip`, { method: 'POST' });
            const previousNextDueDate = result.previousNextDueDate ?? null;

            const undoData = {
                billId: billId,
                previousNextDueDate: previousNextDueDate,
                action: 'skip'
            };
            this._undoData = undoData;

            await this.loadBillsView();

            showUndoNotification(
                t('budget', 'Payment skipped. Advanced to next due date.'),
                () => this.undoSkipPayment(undoData),
                () => this._dropUndo(undoData)
            );

        } catch (error) {
            console.error('Failed to skip bill payment:', error);
            showError(t('budget', 'Failed to skip bill payment'));
        }
    }

    /** @param {object} undoData - The skip to undo (see undoMarkBillPaid) */
    async undoSkipPayment(undoData = this._undoData) {
        if (!undoData || undoData.spent || undoData.action !== 'skip') {
            return;
        }
        undoData.spent = true;

        try {
            const { billId, previousNextDueDate } = undoData;

            await apiFetch(`/apps/budget/api/bills/${billId}/undo-skip`, {
                method: 'POST',
                body: { previousNextDueDate: previousNextDueDate },
            });

            if (this._undoData === undoData) this._undoData = null;
            await this.loadBillsView();

            showSuccess(t('budget', 'Action undone'));
        } catch (error) {
            console.error('Failed to undo skip:', error);
            showError(t('budget', 'Failed to undo action: {message}', { message: error.message }));
        }
    }

    async detectBills() {
        const detectBtn = document.getElementById('detect-bills-btn');
        detectBtn.disabled = true;
        detectBtn.innerHTML = `<span class="icon-loading-small" aria-hidden="true"></span> ${t('budget', 'Detecting...')}`;

        try {
            const detected = await apiFetch('/apps/budget/api/bills/detect?months=6');

            if (!detected || detected.length === 0) {
                showInfo(t('budget', 'No recurring transactions detected'));
                return;
            }

            this.renderDetectedBills(detected);
            document.getElementById('detected-bills-panel').style.display = 'flex';
        } catch (error) {
            console.error('Failed to detect bills:', error);
            showError(t('budget', 'Failed to detect recurring bills'));
        } finally {
            detectBtn.disabled = false;
            detectBtn.innerHTML = `<span class="icon-search" aria-hidden="true"></span> ${t('budget', 'Detect Bills')}`;
        }
    }

    renderDetectedBills(detected) {
        const list = document.getElementById('detected-bills-list');

        list.innerHTML = detected.map((item, index) => {
            const confidenceClass = item.confidence >= 0.8 ? 'high' : item.confidence >= 0.5 ? 'medium' : 'low';
            const confidencePercent = Math.round(item.confidence * 100);

            return `
                <div class="detected-bill-item" data-index="${index}">
                    <div class="detected-bill-select">
                        <input type="checkbox" id="detected-${index}" ${item.confidence >= 0.7 ? 'checked' : ''}>
                    </div>
                    <div class="detected-bill-info">
                        <label for="detected-${index}" class="detected-bill-name">${dom.escapeHtml(item.description || item.name)}</label>
                        <div class="detected-bill-meta">
                            <span class="detected-amount">${formatters.formatCurrency(item.avgAmount || item.amount, accountCurrency(this.accounts, item.accountId), this.settings)}</span>
                            <span class="detected-frequency">${item.frequency}</span>
                            <span class="detected-confidence ${confidenceClass}">${/* xgettext:no-javascript-format */ t('budget', '{percent}% confidence', { percent: confidencePercent })}</span>
                        </div>
                    </div>
                </div>
            `;
        }).join('');

        // Store detected bills for later use
        this._detectedBills = detected;
    }

    /** One at a time: a double click created two (see utils/submitGuard.js) */
    addSelectedDetectedBills() {
        return once('bills-add-detected', document.getElementById('add-selected-bills-btn'), () => this._addSelectedDetectedBills());
    }

    async _addSelectedDetectedBills() {
        const checkboxes = document.querySelectorAll('#detected-bills-list input[type="checkbox"]:checked');
        const selectedIndices = Array.from(checkboxes).map(cb => parseInt(cb.id.replace('detected-', '')));

        if (selectedIndices.length === 0) {
            showWarning(t('budget', 'Please select at least one bill to add'));
            return;
        }

        const billsToAdd = selectedIndices.map(i => this._detectedBills[i]);

        try {
            const result = await apiFetch('/apps/budget/api/bills/create-from-detected', {
                method: 'POST',
                body: { bills: billsToAdd },
            });
            document.getElementById('detected-bills-panel').style.display = 'none';
            showSuccess(n('budget', '%n bill added successfully', '%n bills added successfully', result.created));
            await this.loadBillsView();
        } catch (error) {
            console.error('Failed to add bills:', error);
            showError(t('budget', 'Failed to add selected bills'));
        }
    }

    /**
     * Get custom months pattern from checkboxes as JSON string.
     * @returns {string|null} JSON pattern or null if no months selected
     */
    getCustomMonthsPattern() {
        const checkboxes = document.querySelectorAll('#bill-custom-months input[type="checkbox"]:checked');
        const selectedMonths = Array.from(checkboxes).map(cb => parseInt(cb.value));

        if (selectedMonths.length === 0) {
            return null;
        }

        // Sort months in ascending order
        selectedMonths.sort((a, b) => a - b);

        return JSON.stringify({ months: selectedMonths });
    }

    /**
     * Set custom months checkboxes from JSON pattern.
     * @param {string} pattern JSON pattern string
     */
    async loadBillTagSets(categoryId, existingBill = null) {
        const container = document.getElementById('bill-tags-container');
        if (!container) return;

        try {
            // Load global tags and category tag sets in parallel
            const [globalTagsResponse, categoryTagSets] = await Promise.all([
                apiFetch('/apps/budget/api/tags/global').catch(() => []),
                categoryId ? apiFetch(`/apps/budget/api/tag-sets?categoryId=${categoryId}`).catch(() => []) : Promise.resolve([])
            ]);

            // Get existing tag IDs if editing
            const existingTagIds = existingBill?.tagIds || [];

            // Hidden tags are not offered, except ones already on this bill
            // (#373) — saving reads every checked box, so an unlisted tag
            // would be stripped on the next edit.
            const globalTags = offerableTags(globalTagsResponse || [], existingTagIds);
            const tagSets = offerableTagSets(categoryTagSets || [], existingTagIds);

            if (globalTags.length === 0 && tagSets.length === 0) {
                container.innerHTML = '';
                return;
            }

            let html = '';

            // Global tags section
            if (globalTags.length > 0) {
                html += `
                    <div class="form-group tag-set-selector">
                        <label class="tag-set-label">${t('budget', 'Tags')}</label>
                        <div class="tag-options" style="display: flex; flex-wrap: wrap; gap: 6px; margin-top: 4px;">
                            ${globalTags.map(tag => `
                                <label class="tag-option" style="cursor: pointer;">
                                    <input type="checkbox" class="bill-tag-checkbox"
                                           value="${tag.id}"
                                           data-tag-set-id="global"
                                           ${existingTagIds.includes(tag.id) ? 'checked' : ''}
                                           style="display: none;">
                                    <span class="tag-badge" style="background-color: ${tag.color || '#666'}; color: white; padding: 4px 10px; border-radius: 12px; font-size: 12px; display: inline-block; opacity: ${existingTagIds.includes(tag.id) ? '1' : '0.5'};">
                                        ${dom.escapeHtml(tag.name)}
                                    </span>
                                </label>
                            `).join('')}
                        </div>
                    </div>
                `;
            }

            // Category tag sets
            tagSets.forEach(tagSet => {
                html += `
                    <div class="form-group tag-set-selector">
                        <label class="tag-set-label">${dom.escapeHtml(tagSet.name)}</label>
                        <div class="tag-options" style="display: flex; flex-wrap: wrap; gap: 6px; margin-top: 4px;">
                            ${tagSet.tags && tagSet.tags.length > 0 ? tagSet.tags.map(tag => `
                                <label class="tag-option" style="cursor: pointer;">
                                    <input type="checkbox" class="bill-tag-checkbox"
                                           value="${tag.id}"
                                           data-tag-set-id="${tagSet.id}"
                                           ${existingTagIds.includes(tag.id) ? 'checked' : ''}
                                           style="display: none;">
                                    <span class="tag-badge" style="background-color: ${tag.color || '#666'}; color: white; padding: 4px 10px; border-radius: 12px; font-size: 12px; display: inline-block; opacity: ${existingTagIds.includes(tag.id) ? '1' : '0.5'};">
                                        ${dom.escapeHtml(tag.name)}
                                    </span>
                                </label>
                            `).join('') : `<span style="color: #999; font-size: 11px; font-style: italic;">${t('budget', 'No tags defined')}</span>`}
                        </div>
                    </div>
                `;
            });

            container.innerHTML = html;

            // Add click handlers for tag selection (one per tag set, multi-select for global)
            container.querySelectorAll('.bill-tag-checkbox').forEach(checkbox => {
                checkbox.addEventListener('change', (e) => {
                    const tagSetId = e.target.dataset.tagSetId;
                    // Deselect other tags in same tag set (radio-like behavior, not for global tags)
                    if (e.target.checked && tagSetId !== 'global') {
                        container.querySelectorAll(`.bill-tag-checkbox[data-tag-set-id="${tagSetId}"]`).forEach(cb => {
                            if (cb !== e.target) {
                                cb.checked = false;
                                cb.closest('.tag-option').querySelector('.tag-badge').style.opacity = '0.5';
                            }
                        });
                    }
                    // Update visual state
                    e.target.closest('.tag-option').querySelector('.tag-badge').style.opacity = e.target.checked ? '1' : '0.5';
                });
            });
        } catch (error) {
            console.error('Failed to load tag sets:', error);
            container.innerHTML = '';
        }
    }

    getSelectedBillTagIds() {
        const container = document.getElementById('bill-tags-container');
        if (!container) return [];
        return Array.from(container.querySelectorAll('.bill-tag-checkbox:checked'))
            .map(cb => parseInt(cb.value));
    }

    setCustomMonthsFromPattern(pattern) {
        // Clear all checkboxes first
        document.querySelectorAll('#bill-custom-months input[type="checkbox"]').forEach(cb => cb.checked = false);

        try {
            const parsed = JSON.parse(pattern);
            if (parsed && parsed.months && Array.isArray(parsed.months)) {
                parsed.months.forEach(month => {
                    const checkbox = document.querySelector(`#bill-custom-months input[value="${month}"]`);
                    if (checkbox) {
                        checkbox.checked = true;
                    }
                });
            }
        } catch (e) {
            console.error('Failed to parse custom recurrence pattern:', e);
        }
    }
}
